queries.teams:
SELECT ?team ?teamLabel WHERE {
  ?team wdt:P31 wd:Q135408445 .
  OPTIONAL { ?team rdfs:label ?teamLabel . FILTER(LANG(?teamLabel) = "en") }
}

queries.stints:
SELECT ?player ?team ?st ?rank ?start ?end ?caps ?goals WHERE {
  ?team wdt:P31 wd:Q135408445 .
  ?player p:P54 ?st .
  ?st ps:P54 ?team ;
    wikibase:rank ?rank ;
    pq:P580 ?start .
  OPTIONAL { ?st pq:P582 ?end }
  OPTIONAL { ?st pq:P1350 ?caps }
  OPTIONAL { ?st pq:P1351 ?goals }
  FILTER(YEAR(?start) <= 1994)
}

queries.players:
SELECT ?player (SAMPLE(?en) AS ?label) (SAMPLE(?mul) AS ?mulLabel) (MIN(?born) AS ?birth) (SAMPLE(?article) AS ?enwiki) WHERE {
  { SELECT DISTINCT ?player WHERE {
    ?team wdt:P31 wd:Q135408445 .
    ?player p:P54 ?st .
    ?st ps:P54 ?team ;
      pq:P580 ?start .
    FILTER(YEAR(?start) <= 1994)
  } }
  OPTIONAL { ?player rdfs:label ?en . FILTER(LANG(?en) = "en") }
  OPTIONAL { ?player rdfs:label ?mul . FILTER(LANG(?mul) = "mul") }
  OPTIONAL { ?player wdt:P569 ?born }
  OPTIONAL { ?article schema:about ?player ; schema:isPartOf <https://en.wikipedia.org/> }
} GROUP BY ?player

queries.positions:
SELECT DISTINCT ?player ?position WHERE {
  { SELECT DISTINCT ?player WHERE {
    ?team wdt:P31 wd:Q135408445 .
    ?player p:P54 ?st .
    ?st ps:P54 ?team ;
      pq:P580 ?start .
    FILTER(YEAR(?start) <= 1994)
  } }
  ?player wdt:P413 ?position .
}
